-- Official reference data, not demo seed. Resolution 1685/NQ-UBTVQH15.
-- 113 wards, 54 communes, one special zone; effective 2025-07-01.
-- Source: https://xaydungchinhsach.chinhphu.vn/toan-van-nghi-quyet-so-1685-nq-ubtvqh15-sap-xep-cac-dvhc-cap-xa-cua-thanh-pho-ho-chi-minh-nam-2025-119250616211341304.htm
-- IDs are internal database IDs, not official administrative codes.
CREATE TABLE administrative_units (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    province VARCHAR(100) NOT NULL,
    name VARCHAR(100) NOT NULL,
    unit_type VARCHAR(20) NOT NULL CHECK (unit_type IN ('WARD','COMMUNE','SPECIAL_ZONE')),
    effective_from DATE NOT NULL,
    source_url TEXT NOT NULL,
    UNIQUE (province, name)
);
